// The bundled district files (generated by apps/mobile/tools/gen-districts.mjs) are sound: every
// city is in the catalogue, ids are unique, rings are closed, and the data stays small enough to ship
// in the app bundle.
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';

import { CITY_CATALOG } from '../../contexts/territory/domain/city-catalog';
import { districtAreaM2, districtContains, type Ring } from '../../contexts/territory/domain/district';
import { bundledDistricts, DISTRICT_CITY_IDS } from '..';
import { DISTRICT_FILES } from '../data';

const DATA = path.join(__dirname, '..', 'data');
const KB = 1024;
/** Per city and in all (minified JSON): the plan's size budget (docs/plans/districts-2026-10-29.md). */
const CITY_BUDGET = 60 * KB;
const TOTAL_BUDGET = 1024 * KB;

/**
 * A point well inside a ring: the middle of the widest stretch inside it along the ring's middle
 * latitude (works for concave shapes, unlike the centroid).
 */
function interiorPoint(ring: Ring): [number, number] {
  const lats = ring.map((p) => p[1]);
  const lat = (Math.min(...lats) + Math.max(...lats)) / 2 + 1e-7;
  const xs: number[] = [];
  for (let i = 0; i < ring.length - 1; i++) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[i + 1];
    if (y1 > lat !== y2 > lat) {
      xs.push(x1 + ((lat - y1) * (x2 - x1)) / (y2 - y1));
    }
  }
  xs.sort((a, b) => a - b);
  let best: [number, number] = [ring[0][0], ring[0][1]];
  let widest = -1;
  for (let i = 0; i + 1 < xs.length; i += 2) {
    if (xs[i + 1] - xs[i] > widest) {
      widest = xs[i + 1] - xs[i];
      best = [(xs[i] + xs[i + 1]) / 2, lat];
    }
  }
  return best;
}

const files = readdirSync(DATA).filter((f) => f.endsWith('.json'));

describe('bundled districts', () => {
  it('index.ts lists exactly the JSON files in data/', () => {
    expect(Object.keys(DISTRICT_FILES).sort()).toEqual(files.map((f) => f.replace(/\.json$/, '')).sort());
    expect(DISTRICT_CITY_IDS).toEqual(Object.keys(DISTRICT_FILES).sort());
  });

  it('stays within the size budget', () => {
    let total = 0;
    for (const f of files) {
      const size = statSync(path.join(DATA, f)).size;
      total += size;
      expect({ f, ok: size <= CITY_BUDGET }).toEqual({ f, ok: true });
    }
    expect(total).toBeLessThanOrEqual(TOTAL_BUDGET);
  });

  it.each(Object.entries(DISTRICT_FILES))(
    '%s: a catalogue city with sound, named, closed districts',
    (cityId, load) => {
      const file = load();
      expect(file.cityId).toBe(cityId);
      expect(CITY_CATALOG.some((c) => c.id === cityId)).toBe(true);
      expect(file.districts.length).toBeGreaterThanOrEqual(3);
      const ids = new Set(file.districts.map((d) => d.id));
      expect(ids.size).toBe(file.districts.length);
      for (const d of file.districts) {
        expect(d.name.trim()).not.toBe('');
        expect(d.polygons.length).toBeGreaterThan(0);
        for (const ring of d.polygons.flat()) {
          expect(ring.length).toBeGreaterThanOrEqual(4);
          expect(ring[0]).toEqual(ring.at(-1));
        }
      }
      // Every district has some area, and the city's districts together are a city, not a continent.
      const districts = bundledDistricts.districtsOf(cityId);
      const km2 = districts.map((d) => districtAreaM2(d) / 1e6);
      expect(Math.min(...km2)).toBeGreaterThan(0.05);
      expect(km2.reduce((a, b) => a + b, 0)).toBeLessThan(1500);
      // Districts don't overlap: a point inside each one lies in no other district of the city.
      for (const d of districts) {
        const [lon, lat] = interiorPoint(d.polygons[0][0]);
        expect(districtContains(d, lon, lat)).toBe(true);
        const others = districts.filter((o) => o.id !== d.id && districtContains(o, lon, lat)).map((o) => o.name);
        expect({ district: d.name, overlaps: others }).toEqual({ district: d.name, overlaps: [] });
      }
    }
  );

  it('answers no districts for a city without data, and the same objects on a second read', () => {
    expect(bundledDistricts.districtsOf('xx-nowhere')).toEqual([]);
    const [first] = DISTRICT_CITY_IDS;
    if (first) {
      expect(bundledDistricts.districtsOf(first)).toBe(bundledDistricts.districtsOf(first));
    }
  });
});

// Keep JSON parse honest: the files are what index.ts imports.
it('every data file parses as JSON', () => {
  for (const f of files) {
    expect(() => JSON.parse(readFileSync(path.join(DATA, f), 'utf8'))).not.toThrow();
  }
});
